41		if profile != nil && profile.Version != "" {
42			version = profile.Version
43		}
44		server := sdkmcp.NewServer(&sdkmcp.Implementation{
45			Name:    "memos",
46			Version: version,
47		}, nil)
48	
49		adapter := newAPIAdapter(echoServer)
50		for _, tool := range tools {
51			operation := operationsByTool[tool.Name]
52			server.AddTool(tool, newMCPToolHandler(adapter, operation))
53		}
